<script lang="ts">
  import {untrack} from 'svelte';import {rpc,bytes,type Download} from '../lib/api';import {notify} from '../lib/ui';import {downloadState,refreshDownloads as refresh} from '../lib/download-monitor';import Icon from './Icon.svelte';
  let {openFolder,newDownload,revision}:{openFolder:(p:string)=>void;newDownload:(url?:string,filename?:string)=>void;revision:number}=$props();
  const jobs=$derived($downloadState.jobs);const error=$derived($downloadState.error);const busy=$derived($downloadState.busy);const speeds=$derived($downloadState.speeds);
  $effect(()=>{revision;untrack(()=>{void refresh();});});
  async function retry(job:Download){if(!job.url||job.authenticated||job.method==='POST'||job.headerCount>0){notify('Reopen the source in the browser to capture a fresh request and choose its destination. Temporary credentials were removed.');return;}newDownload(job.url,job.filename);}
  async function clearHistory(){try{await rpc('download_clear',{});await refresh(true);}catch(e){notify(e);}}
</script>
<div class="app-column downloads-app"><div class="toolbar"><span class="muted">SERVER DOWNLOADS</span><span class="spacer"></span><button disabled={busy} onclick={clearHistory}>Clear finished history</button><button disabled={busy} onclick={()=>{void refresh(true);}}><Icon name="refresh" size={16}/> Refresh</button><button class="primary" onclick={()=>newDownload()}><Icon name="plus" size={16}/> New download</button></div>
{#if error}<div class="error-box">{error}</div>{/if}<div class="download-list">{#each jobs as job}<article class="download-card"><div class="download-icon"><Icon name={job.status==='Completed'?'check':job.status==='Failed'?'close':'downloads'} size={24}/></div><div class="download-details"><strong>{job.filename}</strong><div class="muted ellipsis">{job.directory}</div><div class="download-progress" class:indeterminate={!job.total&&(job.status==='Downloading'||!job.persistent&&job.status==='Starting')}><div style:width={job.total?`${Math.min(100,100*job.downloaded/job.total)}%`:'0%'}></div></div><div class="download-meta"><span class:failed={job.status==='Failed'}>{job.status}</span><span>{bytes(job.downloaded)}{job.total?` / ${bytes(job.total)} · ${Math.round(job.downloaded/job.total*100)}%`:' · total unknown'}</span>{#if speeds[job.id]>0}<span>{bytes(speeds[job.id])}/s</span>{/if}<span>{job.backend} · {job.persistent?'detached':job.status==='Starting'?'browser → Windows · keep tab open':'Windows → SFTP · keep client open'}</span></div><small class="muted">Started {new Date(job.started*1000).toLocaleString()}</small>{#if job.error}<pre class="download-error">{job.error}</pre>{/if}</div><div class="download-actions">{#if ['Waiting','Starting','Downloading'].includes(job.status)}<button title="Cancel" onclick={async()=>{try{await rpc('download_cancel',{id:job.id});}catch(e){notify(e);}}}><Icon name="close" size={16}/></button>{:else if job.status!=='Completed'}<button onclick={()=>retry(job)}><Icon name="refresh" size={16}/> Retry</button>{/if}<button title="Open destination folder" onclick={()=>openFolder(job.directory)}><Icon name="files" size={17}/> Open Folder</button></div></article>{/each}{#if !jobs.length&&!busy}<div class="empty-state"><Icon name="downloads" size={40}/><h3>Give your server the download</h3><p>Browse locally. Save files directly to FreeBSD or Linux.</p><button class="primary" onclick={()=>newDownload()}>Download a direct URL</button></div>{/if}</div><div class="statusbar">{jobs.length} jobs <span>Direct jobs stay remote; client transfers are labeled</span></div></div>
